/**
 * The system map's data model.
 *
 * The admin system map wants one structured graph it can draw six ways, so the
 * graph is data, not markup: a list of nodes and edges per view, plus the view's
 * own layout request. Three of the six views are authored by hand in
 * `docs/system/graph.json` (the pipeline, the trigger paths, and the module map);
 * the other three are generated by `scripts/system-graph.mjs` from sources the
 * repo already keeps machine-readable (the SYSTEM.md invariants table and its
 * boundaries section, the decision log, and the Drizzle schema), then merged into
 * `apps/web/src/lib/system-graph.generated.json`.
 *
 * This file holds shapes only. The parsing and merge are pure functions in
 * `system-graph-parse.mjs`, kept in plain JavaScript with JSDoc types so both the
 * Node generator and the Vitest suite can import them with no build step.
 *
 * The node and view shapes below are the contract three other sessions build
 * against. Do not change them without updating them too.
 */

/** What a node stands for, so the canvas can colour and shape it. */
export type NodeKind =
	'stage' | 'module' | 'boundary' | 'decision' | 'data' | 'route' | 'test' | 'trigger';

export interface GraphNode {
	id: string;
	label: string;
	kind: NodeKind;
	/** A short plain sentence shown when the node is opened. Never a distance or a unit. */
	note?: string;
	/** Where the node's own source lives, so the granular detail is clickable. */
	href?: string;
}

export interface GraphEdge {
	from: string;
	to: string;
	/** A short label for the edge: the trigger or the condition it stands for. */
	label?: string;
}

/** The six views the map offers, in the order they are drawn. */
export type GraphViewId = 'pipeline' | 'paths' | 'rules' | 'why' | 'data' | 'granular';

export interface GraphViewLayout {
	engine: 'elk';
	algorithm: 'layered';
	direction: 'TB' | 'LR';
	edgeRouting: 'POLYLINE';
}

export interface GraphView {
	id: GraphViewId;
	title: string;
	lede: string;
	layout: GraphViewLayout;
	nodes: GraphNode[];
	edges: GraphEdge[];
}

export interface SystemGraph {
	version: 1;
	generatedAt: string;
	fingerprint: string;
	views: GraphView[];
}

/* ------------------------- shapes the parsers produce ------------------------- */

/** One row of SYSTEM.md's invariants table. */
export interface InvariantRow {
	id: string;
	invariant: string;
	enforcedBy: string;
	testFile: string;
	kind: string;
}

/** One bullet of SYSTEM.md's boundaries section. */
export interface BoundaryBullet {
	id: string;
	title: string;
	body: string;
}

/** One entry of docs/decisions.md. */
export interface DecisionEntry {
	id: string;
	title: string;
	date: string;
	decided: string;
	why: string;
	rulesOut: string;
	/** The GitHub heading anchor the entry links to. */
	anchor: string;
	href: string;
}

/** One Drizzle table, with the local variable it is bound to. */
export interface SchemaTable {
	name: string;
	varName: string;
}

/** One foreign-key reference from a Drizzle table to another. */
export interface SchemaRef {
	from: string;
	to: string;
	/** The local foreign-key column, when it can be read from the definition. */
	column: string | null;
}

export interface SchemaGraph {
	tables: SchemaTable[];
	refs: SchemaRef[];
}

/* --------------------------- the authored file shape --------------------------- */

/** One module in the hand-kept module map that the granular view draws. */
export interface ModuleEntry {
	id: string;
	label: string;
	/** Defaults to 'module'. */
	kind?: NodeKind;
	/** What the module computes, in one plain sentence. */
	computes: string;
	/** What it is allowed to decide, in one plain sentence. */
	mayDecide: string;
	/** The file the module lives in. */
	href: string;
	/** Test files that guard it, linked to the SYSTEM.md test nodes in granular. */
	guardedBy?: string[];
}

/** A hand-kept label or grouping for a table the schema names too terse. */
export interface TableOverride {
	label?: string;
	group?: string;
}

/** The authored views and the hand-kept module map, read from docs/system/graph.json. */
export interface AuthoredGraph {
	version: 1;
	pipeline: GraphView;
	paths: GraphView;
	modules: ModuleEntry[];
	tableOverrides?: Record<string, TableOverride>;
}
